ALTER TABLE public.polls ADD COLUMN IF NOT EXISTS image text NOT NULL DEFAULT '', ADD COLUMN IF NOT EXISTS "endsAt" timestamp with time zone;
ALTER TABLE public.players ADD COLUMN IF NOT EXISTS season text NOT NULL DEFAULT '2026', ADD COLUMN IF NOT EXISTS "userId" integer REFERENCES public.users(id) ON DELETE SET NULL;
ALTER TABLE public.matches ADD COLUMN IF NOT EXISTS "sheetNumber" integer, ADD COLUMN IF NOT EXISTS supervisor text NOT NULL DEFAULT '', ADD COLUMN IF NOT EXISTS "refereeNames" jsonb NOT NULL DEFAULT '[]', ADD COLUMN IF NOT EXISTS "motmPlayerId" integer REFERENCES public.players(id) ON DELETE SET NULL;
CREATE TABLE public.suspensions (id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, "playerId" integer NOT NULL REFERENCES public.players(id) ON DELETE CASCADE, "teamId" integer NOT NULL REFERENCES public.teams(id), "tournamentId" integer NOT NULL REFERENCES public.tournaments(id), type text NOT NULL DEFAULT 'عقوبة إدارية', "matchCount" integer NOT NULL DEFAULT 1, "issuedOn" text NOT NULL, "startMatchId" integer NOT NULL REFERENCES public.matches(id), "endsAt" timestamp with time zone, active boolean NOT NULL DEFAULT true);
GRANT ALL ON public.suspensions TO service_role;
ALTER TABLE public.suspensions ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.staff (id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name text NOT NULL, "teamId" integer REFERENCES public.teams(id) ON DELETE SET NULL, role text NOT NULL DEFAULT 'coach', age integer, photo text NOT NULL DEFAULT '', bio text NOT NULL DEFAULT '', "userId" integer REFERENCES public.users(id) ON DELETE SET NULL);
GRANT ALL ON public.staff TO service_role;
ALTER TABLE public.staff ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.validate_poll_vote() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN IF NOT EXISTS (SELECT 1 FROM public.polls p WHERE p.id=NEW."pollId" AND p.active AND (p."endsAt" IS NULL OR p."endsAt">now()) AND EXISTS (SELECT 1 FROM jsonb_array_elements(p.options) o WHERE (o->>'id')::integer=NEW."optionId")) THEN RAISE EXCEPTION 'الاستفتاء مغلق أو الخيار غير صالح'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER validate_poll_vote_before_insert BEFORE INSERT ON public.poll_votes FOR EACH ROW EXECUTE FUNCTION public.validate_poll_vote();